const checkSoItemDuplication2 = async () => {
    try {
        const db = await (0, mongdodb_config_1.getDb)("netsuite");
        const dumpCollection = db.collection("dump_sales_order");
        const dummyCollection = db.collection("suite_sales_order");
        const [dumpDocs, dummyDocs] = await Promise.all([
            dumpCollection
                .find({})
                .project({
                "so.items": 1,
                "so.otherRefNum": 1,
                "so.otherrefnum": 1,
            })
                .toArray(),
            dummyCollection
                .find({})
                .project({
                items: 1,
                otherrefnum: 1,
            })
                .toArray(),
        ]);
        const dummyMap = new Map();
        dummyDocs.forEach((doc) => {
            const ref = String(doc.otherrefnum || "")
                .toUpperCase()
                .trim();
            if (ref)
                dummyMap.set(ref, doc);
        });
        const discrepantSOs = new Set();
        for (const dumpDoc of dumpDocs) {
            const so = dumpDoc.so;
            if (!so?.items || !Array.isArray(so.items))
                continue;
            const otherRefNum = so.otherRefNum || so.otherrefnum;
            if (!otherRefNum)
                continue;
            // Find duplicate SKUs within dump
            const itemCountsMap = new Map();
            so.items.forEach((itemLine) => {
                const sku = itemLine.item?.name || itemLine.item?.id;
                if (sku) {
                    itemCountsMap.set(sku, (itemCountsMap.get(sku) || 0) + 1);
                }
            });
            const duplicateSkus = Array.from(itemCountsMap.entries())
                .filter(([_, count]) => count > 1)
                .map(([sku]) => sku);
            if (duplicateSkus.length === 0)
                continue;
            const normalizedRef = String(otherRefNum).toUpperCase().trim();
            const dummyDoc = dummyMap.get(normalizedRef);
            if (!dummyDoc)
                continue;
            // Build dummy item maps
            const dummyItemCountsMap = new Map();
            const dummyItemQtyMap = new Map();
            if (dummyDoc.items && Array.isArray(dummyDoc.items)) {
                dummyDoc.items.forEach((itemLine) => {
                    const sku = itemLine.item;
                    if (sku) {
                        dummyItemCountsMap.set(sku, (dummyItemCountsMap.get(sku) || 0) + 1);
                        dummyItemQtyMap.set(sku, (dummyItemQtyMap.get(sku) || 0) +
                            (Number(itemLine.quantity) || 0));
                    }
                });
            }
            // Check each duplicate SKU for discrepancy condition
            let hasDiscrepancy = false;
            for (const sku of duplicateSkus) {
                const dumpCount = itemCountsMap.get(sku);
                const dummyCount = dummyItemCountsMap.get(sku) || 0;
                const dumpQty = so.items
                    .filter((i) => (i.item?.name || i.item?.id) === sku)
                    .reduce((sum, i) => sum + (Number(i.quantity) || 0), 0);
                const dummyQty = dummyItemQtyMap.get(sku) || 0;
                if (dummyCount === 1 || dumpQty !== dummyQty) {
                    hasDiscrepancy = true;
                    break;
                }
            }
            if (hasDiscrepancy) {
                discrepantSOs.add(normalizedRef);
            }
        }
        return Array.from(discrepantSOs);
    }
    catch (error) {
        console.error("Error checking SO item duplication:", error);
        return [];
    }
};
